1	import fs from 'fs';
2	import path from 'path';
3	import matter from 'gray-matter';
4	import { marked } from 'marked';
5	import Prism from 'prismjs';
6	import 'prismjs/components/prism-python.js';
7	
8	const postsDirectory = path.join(process.cwd(), 'content/blog');
9	
10	// Configure marked options for better HTML output
11	marked.setOptions({
12	  breaks: true,
13	  gfm: true,
14	});
15	
16	// Parse TLDR block from content
17	function parseTLDR(content) {
18	  const tldrRegex = /:::tldr\n([\s\S]*?)\n:::/;
19	  const match = content.match(tldrRegex);
20	
21	  if (!match) {
22	    return { content, tldrItems: null };
23	  }
24	
25	  const tldrContent = match[1];
26	  const items = tldrContent
27	    .split('\n')
28	    .map(line => line.replace(/^\d+\.\s*/, '').trim())
29	    .filter(line => line.length > 0);
30	
31	  const contentWithoutTLDR = content.replace(tldrRegex, '');
32	
33	  return { content: contentWithoutTLDR, tldrItems: items };
34	}
35	
36	function getHeadingText(tokens) {
37	  return tokens
38	    .map(token => token.tokens ? getHeadingText(token.tokens) : (token.text || ''))
39	    .join('');
40	}
41	
42	function escapeHtml(value) {
43	  return value
44	    .replaceAll('&', '&amp;')
45	    .replaceAll('<', '&lt;')
46	    .replaceAll('>', '&gt;')
47	    .replaceAll('"', '&quot;')
48	    .replaceAll("'", '&#39;');
49	}
