51	export function getBlogPost(slug) {
52	  try {
53	    const fullPath = path.join(postsDirectory, `${slug}.md`);
54	
55	    // Check if file exists
56	    if (!fs.existsSync(fullPath)) {
57	      return null;
58	    }
59	
60	    const fileContents = fs.readFileSync(fullPath, 'utf8');
61	    const { data, content } = matter(fileContents);
62	
63	    // Parse TLDR if present
64	    const { content: contentWithoutTLDR, tldrItems } = parseTLDR(content);
65	
66	    // Build the table of contents while adding matching IDs to headings.
67	    const headings = [];
68	    const usedHeadingIds = new Map();
69	    const renderer = new marked.Renderer();
70	
71	    renderer.heading = function ({ depth, tokens }) {
72	      const headingText = getHeadingText(tokens);
73	      const baseId = headingText
74	        .toLowerCase()
75	        .normalize('NFKD')
76	        .replace(/[^\p{Letter}\p{Number}]+/gu, '-')
77	        .replace(/^-+|-+$/g, '') || 'section';
78	      const duplicateCount = usedHeadingIds.get(baseId) || 0;
79	      const id = duplicateCount ? `${baseId}-${duplicateCount + 1}` : baseId;
80	
81	      usedHeadingIds.set(baseId, duplicateCount + 1);
82	
83	      if (depth >= 2) {
84	        headings.push({ id, text: headingText, depth });
85	      }
86	
87	      return `<h${depth} id="${id}">${this.parser.parseInline(tokens)}</h${depth}>\n`;
88	    };
89	
90	    renderer.code = function ({ text, lang }) {
91	      const requestedLanguage = lang?.trim().split(/\s+/, 1)[0].toLowerCase();
92	      const language = requestedLanguage === 'py' ? 'python' : requestedLanguage;
93	      const grammar = language ? Prism.languages[language] : null;
94	      const code = grammar
95	        ? Prism.highlight(text, grammar, language)
96	        : escapeHtml(text);
97	      const languageClass = grammar ? ` class="language-${language}"` : '';
98	
99	      return `<pre><code${languageClass}>${code}</code></pre>\n`;
100	    };
101	
102	    // Convert markdown to HTML
103	    const htmlContent = marked(contentWithoutTLDR, { renderer });
104	
105	    return {
106	      slug,
107	      title: data.title,
108	      meta_title: data.meta_title,
109	      social_title: data.social_title || data.title,
110	      meta_description: data.meta_description,
111	      published_date: data.published_date,
112	      modified_date: data.modified_date,
113	      content: htmlContent,
114	      headings,
115	      tldrItems
116	    };
117	  } catch (error) {
118	    console.error(`Error reading blog post ${slug}:`, error);
119	    return null;
120	  }
121	}
