123	export function getAllBlogPosts() {
124	  try {
125	    // Check if directory exists
126	    if (!fs.existsSync(postsDirectory)) {
127	      return [];
128	    }
129	
130	    const fileNames = fs.readdirSync(postsDirectory);
131	    const allPostsData = fileNames
132	      .filter(fileName => fileName.endsWith('.md'))
133	      .map(fileName => {
134	        const slug = fileName.replace(/\.md$/, '');
135	        const fullPath = path.join(postsDirectory, fileName);
136	        const fileContents = fs.readFileSync(fullPath, 'utf8');
137	        const { data } = matter(fileContents);
138	        
139	        return {
140	          slug,
141	          title: data.title,
142	          published_date: data.published_date,
143	          modified_date: data.modified_date,
144	          meta_title: data.meta_title,
145	          social_title: data.social_title || data.title,
146	          meta_description: data.meta_description,
147	        };
148	      })
149	      .sort((a, b) => {
150	        if (a.published_date < b.published_date) {
151	          return 1;
152	        } else {
153	          return -1;
154	        }
155	      });
156	
157	    return allPostsData;
158	  } catch (error) {
159	    console.error('Error reading blog posts:', error);
160	    return [];
161	  }
162	}
