3	export async function GET() {
4	    try {
5	      const baseUrl = "https://yogesh.co";
6	      
7	      // Get current date for lastModified
8	      const currentDate = new Date();
9	      
10	      // Define static routes
11	      const staticRoutes = [
12	        {
13	          loc: baseUrl,
14	          lastmod: currentDate.toISOString(),
15	          changefreq: 'daily',
16	          priority: 1.0,
17	        }
18	      ];
19	
20	      // Get all blog posts for dynamic routes
21	      const blogPosts = getAllBlogPosts();
22	      const blogRoutes = blogPosts.map(post => ({
23	        loc: `${baseUrl}/${post.slug}`,
24	        lastmod: post.modified_date ? new Date(post.modified_date).toISOString() : new Date(post.published_date).toISOString(),
25	        changefreq: 'weekly',
26	        priority: 0.8,
27	      }));
28	  
29	      // Combine static and dynamic routes
30	      const allRoutes = [...staticRoutes, ...blogRoutes];
31	
32	      // Generate XML for all routes
33	      const routesXml = allRoutes.map(route => `
34	      <url>
35	        <loc>${route.loc}</loc>
36	        <lastmod>${route.lastmod}</lastmod>
37	        <changefreq>${route.changefreq}</changefreq>
38	        <priority>${route.priority}</priority>
39	      </url>
40	      `).join('');
41	  
42	      // Generate XML with both static routes and dynamic blog routes
43	      const xml = `<?xml version="1.0" encoding="UTF-8"?>
44	  <urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
45	    ${routesXml}
46	  </urlset>`;
47	  
48	      // Add cache control headers to ensure fresh content
49	      const headers = {
50	        'Content-Type': 'application/xml',
51	        'Cache-Control': 'public, max-age=3600, must-revalidate',
52	        // Ensure CORS is properly configured
53	        'Access-Control-Allow-Origin': '*',
54	        'Access-Control-Allow-Methods': 'GET'
55	      };
56	  
57	      return new Response(xml, { headers });
58	    } catch (error) {
59	      console.error('Error generating sitemap:', error);
60	      return new Response('Error generating sitemap', {
61	        status: 500,
62	        headers: {
